package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class ObservationForecast129Test {
 @Test public void chatCarriesPrecisionToNewRequestsAndExplicitReuse()throws Exception{try(var store=new WorkspaceStore(java.nio.file.Files.createTempDirectory("precision-chat129"))){var domain=Domain044Test.domain(store);var g=Domain044Test.task("workflow").put("goal","Create an observation-to-artifact explorer, maximum forecast radius 0.25 metres").put("bindings044",new JSONObject().put("metric",new JSONObject().put("runId",UUID.randomUUID()).put("geometryId",UUID.randomUUID()))).put("options044",new JSONObject());var call=domain.bootstrap(g);assertEquals("workflow.start",call.getString("tool"));assertEquals(.25,call.getJSONObject("args").getDouble("maxForecastRadiusM"),0);assertEquals(ObservationForecast129.POLICY,call.getJSONObject("args").getString("forecastPolicy129"));g.getJSONObject("context044").put("procedureBinding",new JSONObject().put("name","motion-explorer").put("version",1).put("kind",ObservationArtifact128.KIND));call=domain.bootstrap(g);assertEquals("workflow.reuse",call.getString("tool"));assertEquals(.25,call.getJSONObject("args").getDouble("maxForecastRadiusM"),0);g.put("goal","Reuse selected observation-to-artifact explorer");assertFalse(domain.bootstrap(g).getJSONObject("args").has("forecastPolicy129"));g.getJSONObject("context044").remove("procedureBinding");assertFalse(domain.bootstrap(g).getJSONObject("args").has("forecastPolicy129"));}}
 @Test public void explicitPrecisionCannotSilentlyBecomeTheDefault(){assertEquals(.25,ObservationForecast129.chatSettings("maximum forecast radius 0.25 metres").getDouble("maxForecastRadiusM"),0);for(String s:List.of("maximum forecast radius -1 metres","maximum forecast radius infinity","maximum forecast radius 0 metres","maximum forecast radius 1 metres; maximum forecast radius 2 metres"))assertThrows(IllegalArgumentException.class,()->ObservationForecast129.chatSettings(s));}
 static JSONObject definition(){var d=ObservationArtifact128Test.definition().put("forecastPolicy129",ObservationForecast129.POLICY).put("baselineWindowS",.6).put("maxForecastRadiusM",2);return ObservationArtifact128.definition(d);}
 static JSONObject point(int i,double t,double x,double y,double radius){return new JSONObject().put("ordinal",i).put("seconds",t).put("positionM",new JSONArray(new double[]{x,y})).put("radiusM",radius).put("accepted",true).put("status","measured-estimate");}
 static JSONObject source(){var rows=new JSONArray();for(int i=1;i<=30;i++)rows.put(point(i,i*.04,2*i*.04,0,.1));return new JSONObject().put("rows",rows);}
 @Test public void longerBaselineReducesNoiseAmplificationWithoutInventingAccuracy(){var d=definition().put("accelerationBoundMps2",0);var s=source();var old=WorldFrames.copy(d);old.remove("forecastPolicy129");var a=ObservationArtifact128.forecast(s,old);var b=ObservationForecast129.forecast(s,d);assertTrue(b.getJSONObject("future").getBoolean("available"));assertEquals(3.6,b.getJSONObject("future").getJSONArray("positionM").getDouble(0),1e-12);assertEquals(.3,b.getJSONObject("future").getDouble("radiusM"),1e-12);assertTrue(a.getJSONObject("future").getDouble("radiusM")>3);}
 @Test public void accelerationDuringBaselineIsIncludedAndBoundCoversAdversarialEndpointErrors(){var d=definition().put("maxForecastRadiusM",100).put("accelerationBoundMps2",4);for(double ax:new double[]{-4,0,4})for(double e0:new double[]{-.1,.1})for(double e1:new double[]{-.1,.1}){var a=point(1,0,e0,0,.1);var b=point(2,.5,.5*ax*.25+e1,0,.1);var p=ObservationForecast129.predict(List.of(a,b),1,d);double truth=.5*ax;assertTrue(Math.abs(p.getJSONArray("positionM").getDouble(0)-truth)<=p.getDouble("radiusM")+1e-12);assertEquals(.1+.5*.2/.5+.5*4*.5*(.5+.5),p.getDouble("radiusM"),1e-12);}}
 @Test public void precisionBudgetWithholdsInsteadOfSilentlyShrinkingAnInterval(){var d=definition().put("maxForecastRadiusM",.2);var f=ObservationForecast129.forecast(source(),d);var future=f.getJSONObject("future");assertFalse(future.getBoolean("available"));assertTrue(future.getDouble("bestRadiusM")>.2);assertFalse(future.has("positionM"));assertTrue(f.getJSONObject("metrics").getInt("withheldForecasts")>0);}
 @Test public void futureAnnotationsAndRejectedMeasurementsDoNotChangeEarlierForecasts(){var s=source();var d=definition();var before=ObservationForecast129.forecast(s,d);s.getJSONArray("rows").getJSONObject(25).put("positionM",new JSONArray("[999,999]"));var after=ObservationForecast129.forecast(s,d);for(int i=0;i<=25;i++)assertTrue(before.getJSONArray("rows").getJSONObject(i).getJSONObject("forecast").similar(after.getJSONArray("rows").getJSONObject(i).getJSONObject("forecast")));var rejected=source();rejected.getJSONArray("rows").getJSONObject(10).put("accepted",false).put("status","prediction-only").put("positionM",new JSONArray("[999,999]"));var f=ObservationForecast129.forecast(rejected,d);assertEquals(.96,f.getJSONArray("rows").getJSONObject(11).getJSONObject("forecast").getJSONArray("positionM").getDouble(0),1e-12);}
 @Test public void gapsResetBaselinesAndInvalidPoliciesCannotEnter(){var s=source();for(int i=15;i<30;i++)s.getJSONArray("rows").getJSONObject(i).put("seconds",2+i*.04);var f=ObservationForecast129.forecast(s,definition());assertFalse(f.getJSONArray("rows").getJSONObject(15).getJSONObject("forecast").getBoolean("available"));assertFalse(f.getJSONArray("rows").getJSONObject(16).getJSONObject("forecast").getBoolean("available"));assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("forecastPolicy129","invented")));assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("maxForecastRadiusM","1")));assertThrows(IllegalArgumentException.class,()->ObservationArtifact128.definition(definition().put("baselineWindowS",10)));}
 @Test public void durableProcedureKeepsChosenPolicyAndRefusesTooStrictSources()throws Exception{try(var x=new ObservationArtifact128Test.Fixture(java.nio.file.Files.createTempDirectory("forecast129"))){var in=x.input().put("forecastPolicy129",ObservationForecast129.POLICY).put("maxForecastRadiusM",100);var done=ObservationArtifact128Test.complete(x,in);assertTrue(ObservationForecast129.selected(new JSONObject(x.f.artifacts.read(done.getJSONObject("report").getString("id")).getJSONObject("contents").getString("observation.json")).getJSONObject("definition")));assertTrue(x.f.workflows.verifyArchive110(done.getString("id")).getBoolean("passed"));var strict=x.input().put("forecastPolicy129",ObservationForecast129.POLICY).put("maxForecastRadiusM",.001);assertThrows(IllegalArgumentException.class,()->x.f.workflows.start(strict));assertFalse(x.f.goals.workflowReserved());}}
}
